"use client";

import { loadFont as loadSpace } from "@remotion/google-fonts/SpaceGrotesk";
import type React from "react";
import { useId, useMemo } from "react";
import { AbsoluteFill, Easing, interpolate } from "remotion";
import { useSceneConfig, useSceneFrame } from "@/lib/remocn/frame-rate";
import { useGlide } from "@/lib/remocn/glide";
import { type Timing, useTimeline } from "@/lib/remocn/timeline";
import { type FlowArrowElementId, flowArrowTimeline } from "./timeline";

const { fontFamily: space } = loadSpace("normal", {
  weights: ["400", "500"],
  subsets: ["latin"],
});

export interface FlowArrowProps {
  metric?: string;
  label?: string;
  accent?: string;
  /** Text color of the metric; overrides the theme. */
  ink?: string;
  /** Background fill; "transparent" drops it. */
  background?: string;
  /** Typeface for the metric and label. Load it yourself; Space Grotesk by default. */
  fontFamily?: string;
  /** Weight of the metric. */
  fontWeight?: number;
  /** Frames each dot takes to fly into the arrow. */
  flight?: number;
  /** Size of the foreground, around the frame's center. */
  scale?: number;
  /** Frames to hold the first frame before anything moves. */
  delay?: number;
  grain?: boolean;
  theme?: "dark" | "light";
  speed?: number;
  /**
   * Moves, trims or stretches the stray stream, the push, the dots filling
   * the arrow, the baseline, the metric, the shine and the label, by the ids
   * in `./timeline`. Frames on the scene timeline, after `delay` and `speed`.
   */
  timing?: Timing<FlowArrowElementId>;
}

const EASE_IO = Easing.bezier(0.65, 0, 0.35, 1);
const EASE_OUT = Easing.bezier(0.22, 1, 0.36, 1);
const FLIGHT = Easing.bezier(0.38, 0, 0.16, 1);
const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

const THEMES = {
  dark: {
    bg: "#0A0A0B",
    fg: "#F3F2EF",
    muted: "#8B8A90",
    stream: "#7C7B82",
    hair: "rgba(255,255,255,0.14)",
    shine: "#FFFFFF",
    grain: 0.06,
  },
  light: {
    bg: "#F5F4F0",
    fg: "#121214",
    muted: "#6E6C67",
    stream: "#9C9A94",
    hair: "rgba(18,18,20,0.16)",
    shine: "#0E1240",
    grain: 0.045,
  },
} as const;

const TREND: [number, number][] = [
  [0, 0.02],
  [0.15, 0.13],
  [0.26, 0.09],
  [0.42, 0.3],
  [0.52, 0.25],
  [0.69, 0.55],
  [0.78, 0.5],
  [1, 0.9],
];

const PASSERS = 80;

function hash(n: number) {
  const x = Math.sin(n * 127.1 + 311.7) * 43758.5453;
  return x - Math.floor(x);
}

/** gradients.sh "halo" palette, run from the arrow's tail to its tip. */
const HALO = {
  dark: ["#3D4DFF", "#E2457A", "#FFB36B", "#FFF4EC"],
  light: ["#3D4DFF", "#E2457A", "#F2894A"],
} as const;

function sample(stops: readonly string[], k: number) {
  const x = Math.min(1, Math.max(0, k)) * (stops.length - 1);
  const i = Math.min(stops.length - 2, Math.floor(x));
  return mix(stops[i], stops[i + 1], x - i);
}

function mix(a: string, b: string, t: number) {
  const pa = Number.parseInt(a.slice(1), 16);
  const pb = Number.parseInt(b.slice(1), 16);
  const ch = (p: number, s: number) => (p >> s) & 255;
  const c = (s: number) =>
    Math.round(ch(pa, s) + (ch(pb, s) - ch(pa, s)) * t)
      .toString(16)
      .padStart(2, "0");
  return `#${c(16)}${c(8)}${c(0)}`;
}

type Pt = { x: number; y: number };

function catmull(pts: Pt[], steps: number) {
  const out: Pt[] = [];
  for (let i = 0; i < pts.length - 1; i++) {
    const p0 = pts[Math.max(0, i - 1)];
    const p1 = pts[i];
    const p2 = pts[i + 1];
    const p3 = pts[Math.min(pts.length - 1, i + 2)];
    for (let s = 0; s < steps; s++) {
      const t = s / steps;
      const t2 = t * t;
      const t3 = t2 * t;
      const f = (a: number, b: number, c: number, d: number) =>
        0.5 *
        (2 * b +
          (-a + c) * t +
          (2 * a - 5 * b + 4 * c - d) * t2 +
          (-a + 3 * b - 3 * c + d) * t3);
      out.push({ x: f(p0.x, p1.x, p2.x, p3.x), y: f(p0.y, p1.y, p2.y, p3.y) });
    }
  }
  out.push(pts[pts.length - 1]);
  return out;
}

function cubic(a: Pt, b: Pt, c: Pt, d: Pt, t: number): Pt {
  const q = 1 - t;
  const w0 = q * q * q;
  const w1 = 3 * q * q * t;
  const w2 = 3 * q * t * t;
  const w3 = t * t * t;
  return {
    x: w0 * a.x + w1 * b.x + w2 * c.x + w3 * d.x,
    y: w0 * a.y + w1 * b.y + w2 * c.y + w3 * d.y,
  };
}

function Grain({ opacity }: { opacity: number }) {
  const id = `g${useId().replace(/[^a-zA-Z0-9_-]/g, "")}`;
  return (
    <svg
      width="100%"
      height="100%"
      style={{ position: "absolute", inset: 0, opacity, pointerEvents: "none" }}
      aria-hidden
    >
      <filter id={id}>
        <feTurbulence
          type="fractalNoise"
          baseFrequency="0.9"
          numOctaves={2}
          seed={23}
          stitchTiles="stitch"
        />
        <feColorMatrix values="0 0 0 0 0.5  0 0 0 0 0.5  0 0 0 0 0.5  0 0 0 0.9 0" />
      </filter>
      <rect width="100%" height="100%" filter={`url(#${id})`} />
    </svg>
  );
}

function buildArrow(W: number, H: number, u: number) {
  const bx0 = W * 0.13;
  const bw = W * 0.5;
  const by1 = H * 0.78;
  const bh = H * 0.54;
  const knots = TREND.map(([x, y]) => ({ x: bx0 + x * bw, y: by1 - y * bh }));
  const line = catmull(knots, 26);
  const cum = [0];
  for (let i = 1; i < line.length; i++) {
    cum.push(
      cum[i - 1] +
        Math.hypot(line[i].x - line[i - 1].x, line[i].y - line[i - 1].y),
    );
  }
  const L = cum[cum.length - 1];
  const end = line[line.length - 1];
  const prev = line[line.length - 10];
  const dl = Math.hypot(end.x - prev.x, end.y - prev.y) || 1;
  const d = { x: (end.x - prev.x) / dl, y: (end.y - prev.y) / dl };
  const n = { x: -d.y, y: d.x };
  const half = 17 * u;
  const hw = 52 * u;
  const hl = 92 * u;
  const tip = { x: end.x + d.x * hl, y: end.y + d.y * hl };
  const total = L + hl;

  const pitch = 9 * u;
  const rowH = pitch * 0.866;
  const minX = bx0 - half * 2;
  const maxX = tip.x + hw;
  const minY = tip.y - hw;
  const maxY = by1 + half * 2;
  const pts: { x: number; y: number; s: number }[] = [];
  for (let gy = minY, row = 0; gy <= maxY; gy += rowH, row++) {
    const off = row % 2 ? pitch / 2 : 0;
    for (let gx = minX + off; gx <= maxX; gx += pitch) {
      const rx = gx - end.x;
      const ry = gy - end.y;
      const along = rx * d.x + ry * d.y;
      const across = rx * n.x + ry * n.y;
      if (
        along >= -1 &&
        along <= hl &&
        Math.abs(across) <= hw * (1 - along / hl)
      ) {
        pts.push({ x: gx, y: gy, s: (L + along) / total });
        continue;
      }
      if (along > -1) continue;
      let best = Number.POSITIVE_INFINITY;
      let bestS = 0;
      for (let i = 0; i < line.length - 1; i++) {
        const a = line[i];
        const b = line[i + 1];
        const vx = b.x - a.x;
        const vy = b.y - a.y;
        const len2 = vx * vx + vy * vy || 1;
        const k = Math.max(
          0,
          Math.min(1, ((gx - a.x) * vx + (gy - a.y) * vy) / len2),
        );
        const dist = Math.hypot(gx - (a.x + vx * k), gy - (a.y + vy * k));
        if (dist < best) {
          best = dist;
          bestS = cum[i] + (cum[i + 1] - cum[i]) * k;
        }
      }
      if (best <= half) pts.push({ x: gx, y: gy, s: bestS / total });
    }
  }
  return { pts, tip, start: knots[0], by1 };
}

const midway = (p: number) => p > 5e-4 && p < 1 - 5e-4;

/** The foreground at `scale`, around the frame's center; nothing extra at 1. */
function ScaleLayer({
  scale,
  children,
}: {
  scale: number;
  children: React.ReactNode;
}) {
  if (scale === 1) return children;
  return (
    <AbsoluteFill style={{ transform: `scale(${scale})` }}>
      {children}
    </AbsoluteFill>
  );
}

export function FlowArrow(props: FlowArrowProps) {
  const {
    metric = "3×",
    label = "faster growth",
    accent = "#3B5BFD",
    ink,
    background,
    fontFamily = space,
    fontWeight = 400,
    scale = 1,
    delay = 0,
    grain = true,
    theme = "dark",
    speed = 1,
    timing,
  } = props;
  const glide = useGlide();
  const t = Math.max(0, useSceneFrame() - delay) * speed;
  const { width: W, height: H, durationInFrames } = useSceneConfig();
  const tl = useTimeline(
    flowArrowTimeline,
    props,
    durationInFrames * speed,
    timing,
  );
  const streamEl = tl.get("stream");
  const pushEl = tl.get("push");
  const fillEl = tl.get("fill");
  const baseEl = tl.get("baseline");
  const metricEl = tl.get("metric");
  const shineEl = tl.get("shine");
  const labelEl = tl.get("label");
  const launch = fillEl.start;
  const span = fillEl.beat("span");
  const jitter = fillEl.beat("jitter");
  const flight = fillEl.beat("flight");
  const settleLen = fillEl.beat("settle");
  const streamAt = streamEl.start;
  const spread = streamEl.beat("spread");
  const dur = streamEl.beat("dur");
  const vary = streamEl.beat("vary");
  const u = Math.min(W / 1280, H / 720);
  const p = THEMES[theme];
  const fg = ink ?? p.fg;
  // The tail starts in the accent (the palette's own first stop is the same blue).
  const halo = useMemo(
    () => [accent, ...HALO[theme].slice(1)],
    [accent, theme],
  );
  const r = 3.1 * u;

  const arrow = useMemo(() => buildArrow(W, H, u), [W, H, u]);

  const particles = useMemo(
    () =>
      arrow.pts.map((pt, k) => {
        const h = (o: number) => hash(k * 2.31 + o);
        const o = h(1) * 2 - 1;
        const a = { x: -W * 0.05, y: H * (0.56 + o * 0.05) };
        const b = {
          x: a.x + (pt.x - a.x) * 0.42,
          y: H * (0.26 + o * 0.05) + (pt.y - H * 0.5) * 0.35,
        };
        const c = {
          x: pt.x - W * (0.05 + h(5) * 0.03),
          y: pt.y - H * (0.16 + h(6) * 0.05),
        };
        return {
          k,
          s: pt.s,
          color: sample(halo, pt.s ** 1.15),
          a,
          b,
          c,
          d: { x: pt.x, y: pt.y },
          start: launch + pt.s * span + h(7) * jitter,
        };
      }),
    [arrow, W, H, halo, launch, span, jitter],
  );

  const passers = useMemo(
    () =>
      Array.from({ length: PASSERS }, (_, k) => {
        const h = (o: number) => hash(k * 5.17 + 40 + o);
        const o = h(1) * 2 - 1;
        return {
          k,
          a: { x: -W * 0.05, y: H * (0.56 + o * 0.05) },
          b: { x: W * 0.36, y: H * (0.2 + o * 0.06) },
          c: { x: W * 0.7, y: H * (0.62 + o * 0.07) },
          d: { x: W * 1.06, y: H * (0.42 + o * 0.08) },
          start: h(5) * spread + streamAt,
          dur: dur + h(6) * vary,
        };
      }),
    [W, H, streamAt, spread, dur, vary],
  );

  const sweep = interpolate(t, [shineEl.start, shineEl.end], [-0.15, 1.15], {
    ...CLAMP,
    easing: EASE_IO,
  });
  const land = interpolate(t, [metricEl.start, metricEl.end], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });
  const labIn = interpolate(t, [labelEl.start, labelEl.end], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });
  const hairIn = interpolate(t, [baseEl.start, baseEl.end], [0, 1], {
    ...CLAMP,
    easing: EASE_IO,
  });
  const push = interpolate(t, [pushEl.start, pushEl.end], [0, 1], {
    ...CLAMP,
    easing: EASE_IO,
  });
  const zoom = 0.975 + 0.035 * push;

  const marks: React.ReactNode[] = [];
  for (const q of passers) {
    const raw = (t - q.start) / q.dur;
    if (raw <= 0 || raw >= 1) continue;
    const e = EASE_IO(raw);
    const head = cubic(q.a, q.b, q.c, q.d, e);
    const tail = cubic(q.a, q.b, q.c, q.d, Math.max(0, e - 0.025));
    const fade = Math.min(1, Math.sin(Math.PI * raw) * 2);
    marks.push(
      <line
        key={`p${q.k}`}
        x1={tail.x}
        y1={tail.y}
        x2={head.x}
        y2={head.y}
        stroke={p.stream}
        strokeWidth={r * 1.6}
        strokeLinecap="round"
        opacity={0.5 * fade}
      />,
    );
  }
  for (const q of particles) {
    const raw = interpolate(t, [q.start, q.start + flight], [0, 1], CLAMP);
    if (raw <= 0) continue;
    if (raw >= 1) {
      const g = Math.exp(-(((q.s - sweep) / 0.07) ** 2));
      const settle = interpolate(
        t,
        [q.start + flight, q.start + flight + settleLen],
        [1.3, 1],
        CLAMP,
      );
      marks.push(
        <circle
          key={q.k}
          cx={q.d.x}
          cy={q.d.y}
          r={r * settle}
          fill={g > 0.02 ? mix(q.color, p.shine, 0.45 * g) : q.color}
        />,
      );
      continue;
    }
    const e = FLIGHT(raw);
    const head = cubic(q.a, q.b, q.c, q.d, e);
    const tail = cubic(q.a, q.b, q.c, q.d, Math.max(0, e - 0.022));
    const tone = interpolate(raw, [0.35, 0.95], [0, 1], CLAMP);
    marks.push(
      <line
        key={q.k}
        x1={tail.x}
        y1={tail.y}
        x2={head.x}
        y2={head.y}
        stroke={mix(p.stream, q.color, tone)}
        strokeWidth={r * 1.7}
        strokeLinecap="round"
        opacity={interpolate(raw, [0, 0.15], [0.3, 0.95], CLAMP)}
      />,
    );
  }

  const baseY = arrow.by1 + 34 * u;
  const baseX0 = arrow.start.x - 10 * u;
  const baseX1 = W * 0.9;

  return (
    <AbsoluteFill
      style={{
        background:
          background === "transparent" ? undefined : (background ?? p.bg),
        overflow: "hidden",
      }}
    >
      <ScaleLayer scale={scale}>
        <AbsoluteFill
          style={{
            transform: `scale(${zoom})${glide(midway(push))}`,
            transformOrigin: "50% 50%",
          }}
        >
          <svg
            width={W}
            height={H}
            style={{ position: "absolute", inset: 0 }}
            aria-hidden
          >
            <line
              x1={baseX0}
              y1={baseY}
              x2={baseX0 + (baseX1 - baseX0) * hairIn}
              y2={baseY}
              stroke={p.hair}
              strokeWidth={Math.max(1, u)}
            />
            {marks}
          </svg>

          <div
            style={{
              position: "absolute",
              left: arrow.tip.x + 44 * u,
              top: arrow.tip.y - 30 * u,
              display: "flex",
              flexDirection: "column",
              whiteSpace: "nowrap",
            }}
          >
            <div
              style={{
                fontFamily,
                fontWeight,
                fontSize: 176 * u,
                lineHeight: 0.9,
                letterSpacing: "-0.04em",
                color: fg,
                fontVariantNumeric: "tabular-nums",
                opacity: land,
                filter:
                  land < 0.99 ? `blur(${(1 - land) * 8 * u}px)` : undefined,
                transform: `translate(${(1 - land) * -16 * u}px, ${(1 - land) * 14 * u}px)`,
              }}
            >
              {metric}
            </div>
            <div
              style={{
                marginTop: 16 * u,
                fontFamily,
                fontWeight: 400,
                fontSize: 26 * u,
                letterSpacing: "-0.01em",
                color: p.muted,
                opacity: labIn,
                transform: `translateY(${(1 - labIn) * 8 * u}px)`,
              }}
            >
              {label}
            </div>
          </div>
        </AbsoluteFill>
      </ScaleLayer>

      <AbsoluteFill
        style={{
          background: `radial-gradient(ellipse 80% 80% at 50% 50%, transparent 62%, ${p.bg} 100%)`,
          opacity: 0.6,
          pointerEvents: "none",
        }}
      />
      {grain ? <Grain opacity={p.grain} /> : null}
    </AbsoluteFill>
  );
}

import { defineTimeline, type TimelineElement } from "@/lib/remocn/timeline";

// The stray stream passing through, the slow push, the dots flying in to
// fill the arrow, the baseline drawing, then the metric landing, the shine
// sweeping the arrow and the label. Frames on the 30 fps scene timeline,
// after `delay` and `speed`. The ids are public: a saved `timing` prop
// refers to them.

export type FlowArrowElementId =
  | "stream"
  | "push"
  | "fill"
  | "baseline"
  | "metric"
  | "shine"
  | "label";

export interface FlowArrowTimingProps {
  flight?: number;
}

const LAUNCH = 4;
const SPAN = 52;
const JITTER = 8;
const FLY = 32;

// `stream` is the strays that pass by: each starts somewhere in its first
// `spread` frames and takes `dur` plus up to `vary` frames. In `fill` each
// dot launches by its place along the arrow over `span`, plus up to
// `jitter`, flies for `flight` and settles over `settle`. The metric, the
// shine and the label follow the fill.
export const flowArrowTimeline = defineTimeline<
  FlowArrowElementId,
  FlowArrowTimingProps
>(({ flight = FLY }): TimelineElement<FlowArrowElementId>[] => {
  const hit = LAUNCH + SPAN + JITTER + flight;
  const elements: TimelineElement<FlowArrowElementId>[] = [
    {
      id: "stream",
      lane: "Stream",
      label: "strays",
      start: -14,
      length: 54 + 46 + 12,
      beats: { spread: 54, dur: 46, vary: 12 },
    },
    { id: "push", lane: "Camera", label: "push", start: 0, length: hit + 50 },
    {
      id: "fill",
      lane: "Arrow",
      label: "dots fly in",
      start: LAUNCH,
      length: SPAN + JITTER + flight,
      beats: { span: SPAN, jitter: JITTER, flight, settle: 6 },
    },
    { id: "baseline", lane: "Base", label: "baseline", start: 6, length: 54 },
    {
      id: "metric",
      lane: "Metric",
      label: "metric",
      start: hit - 6,
      length: 22,
      follows: "fill",
    },
    {
      id: "shine",
      lane: "Arrow",
      label: "shine",
      start: hit - 2,
      length: 28,
      follows: "fill",
    },
    {
      id: "label",
      lane: "Metric",
      label: "label",
      start: hit + 4,
      length: 18,
      follows: "fill",
    },
  ];
  return elements.sort((a, b) => a.start - b.start);
});
